from rdkit import Chem
from rdkit.Chem import AllChem
rw=Chem.RWMol()
# core atom indices: N1 0; a1 1,b1 2,b2 3,a2 4, M12 5, a3 6, N2 7,b3 8,b4 9,a4 10,M23 11,a5 12,b5 13,b6 14,a6 15,N3 16,M34 17,a8 18,b8 19,b7 20,a7 21,N4 22,M41 23; P24 Cl25,26
names=['N1','a1','b1','b2','a2','M12','a3','N2','b3','b4','a4','M23','a5','b5','b6','a6','N3','M34','a8','b8','b7','a7','N4','M41','P','Cl1','Cl2']
for name in names:
    if name.startswith('N'):
        at=Chem.Atom('N')
        if name in ('N1','N3'): at.SetFormalCharge(1)
    elif name=='P':
        at=Chem.Atom('P'); at.SetFormalCharge(-1)
    elif name.startswith('Cl'): at=Chem.Atom('Cl')
    else: at=Chem.Atom('C')
    rw.AddAtom(at)

def bond(i,j,order=Chem.BondType.SINGLE): rw.AddBond(i,j,order)
S=Chem.BondType.SINGLE; D=Chem.BondType.DOUBLE
# pyrrole1
for i,j,o in [(0,1,S),(1,2,S),(2,3,D),(3,4,S),(4,0,D)]:bond(i,j,o)
# pyrrole2
for i,j,o in [(7,6,S),(6,8,S),(8,9,D),(9,10,S),(10,7,S)]:bond(i,j,o)
# pyrrole3
for i,j,o in [(16,12,D),(12,13,S),(13,14,D),(14,15,S),(15,16,S)]:bond(i,j,o)
# pyrrole4
for i,j,o in [(22,21,S),(21,20,D),(20,19,S),(19,18,D),(18,22,S)]:bond(i,j,o)
# meso bridges
for i,j,o in [(4,5,S),(5,6,D),(10,11,D),(11,12,S),(15,17,D),(17,18,S),(21,23,S),(23,1,D)]:bond(i,j,o)
# phosphorous coordination
for i in [0,7,16,22]:bond(24,i,S)
bond(24,25,S); bond(24,26,S)
# ethyl groups on each beta carbon
for beta in [2,3,8,9,13,14,19,20]:
    c1=rw.AddAtom(Chem.Atom('C')); c2=rw.AddAtom(Chem.Atom('C'))
    bond(beta,c1,S); bond(c1,c2,S)
m=rw.GetMol()
Chem.SanitizeMol(m)
print('formula heavy',m.GetNumAtoms(),Chem.rdMolDescriptors.CalcMolFormula(m))
m=Chem.AddHs(m)
print('all',m.GetNumAtoms(),Chem.rdMolDescriptors.CalcMolFormula(m))
params=AllChem.ETKDGv3(); params.randomSeed=42; params.useMacrocycleTorsions=True; params.useSmallRingTorsions=True
res=AllChem.EmbedMolecule(m,params)
print('embed',res)
if res<0:
  params.maxIterations=1000; res=AllChem.EmbedMolecule(m,params); print('retry',res)
if res>=0:
  print('MMFF props',AllChem.MMFFHasAllMoleculeParams(m))
  if AllChem.MMFFHasAllMoleculeParams(m):
   ff=AllChem.MMFFGetMoleculeForceField(m,AllChem.MMFFGetMoleculeProperties(m)); print('energy before',ff.CalcEnergy()); ff.Minimize(maxIts=1000); print('energy after',ff.CalcEnergy())
  else:
   ff=AllChem.UFFGetMoleculeForceField(m); print('UFF',ff); ff.Minimize(maxIts=1000)
  conf=m.GetConformer()
  with open('/tmp/test.xyz','w') as f:
   f.write(str(m.GetNumAtoms())+'\nfoo\n')
   for a in m.GetAtoms():
    p=conf.GetAtomPosition(a.GetIdx()); f.write(f'{a.GetSymbol()} {p.x:.6f} {p.y:.6f} {p.z:.6f}\n')
